import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static int nextInt() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        int r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] last = {-1, -1, -1};
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int v = nextInt();
            if (v != 0) {
                int other = 3 - v;
                if (last[other] >= 0) best = Math.min(best, i - last[other]);
                last[v] = i;
            }
        }
        System.out.println(best == Integer.MAX_VALUE ? -1 : best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n, c := 0, byte(0)
	c, _ = rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	last := [3]int{-1, -1, -1}
	best := -1
	for i := 0; i < n; i++ {
		v := readInt()
		if v != 0 {
			other := 3 - v
			if last[other] >= 0 && (best < 0 || i-last[other] < best) {
				best = i - last[other]
			}
			last[v] = i
		}
	}
	fmt.Println(best)
}
